import numpy as np

def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_scale = 2.3885755376786504  # OPT_PARAM: {"initial": 2.3885755376786504, "min": 0.5, "max": 3.0, "type": "float"}
    demand_response = 0.1  # OPT_PARAM: {"initial": 0.1, "min": 0.1, "max": 1.0, "type": "float"}
    pipeline_weight = 0.3077956675983579  # OPT_PARAM: {"initial": 0.3077956675983579, "min": 0.0, "max": 0.5, "type": "float"}

    demand_based_target = base_scale * (100.0 + demand_response * (last_demand - 100.0))
    pipeline_adjustment = pipeline_weight * (np.sum(pipeline_orders[:3]) / 3 - 100.0)
    target = max(0.0, demand_based_target + pipeline_adjustment)
    order_amount = max(0.0, target - on_hand_inventory - np.sum(pipeline_orders))
    return order_amount
